-- The season's 8 trainees and the evenings they build.
-- Generated by scripts/assign_trainees.py (an exact search). Idempotent: run as often as needed.
BEGIN;
UPDATE students SET name = 'איתי בן מנחם' WHERE id = 5;
UPDATE students SET name = 'אלה מאיר' WHERE id = 2;
UPDATE students SET name = 'זואה כהן' WHERE id = 1;
UPDATE students SET name = 'יותם ספיר' WHERE id = 6;
UPDATE students SET name = 'כליל בלאוקופף' WHERE id = 9;
UPDATE students SET name = 'רוני פרנקל' WHERE id = 3;
UPDATE students SET name = 'רותם דרור' WHERE id = 7;
DELETE FROM students WHERE id = 4 AND name IN ('איתי בן יהודה', 'חניך 4');   -- assignments cascade; other student_id refs go NULL
DELETE FROM students WHERE id = 8 AND name IN ('יעל שם טוב', 'חניך 8');   -- assignments cascade; other student_id refs go NULL
DELETE FROM students WHERE id = 10 AND name IN ('חניך 10');   -- assignments cascade; other student_id refs go NULL
-- The cancelled evenings (2.11.2026): nothing a delete would lose, or stop here.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM lessons WHERE mishmar_id IN (8, 11)) OR EXISTS (SELECT 1 FROM budget WHERE mishmar_id IN (8, 11)) OR EXISTS (SELECT 1 FROM logistics_items WHERE mishmar_id IN (8, 11)) OR EXISTS (SELECT 1 FROM feedback WHERE mishmar_id IN (8, 11)) OR EXISTS (SELECT 1 FROM tasks WHERE mishmar_id IN (8, 11) AND status <> 'TO DO') THEN RAISE EXCEPTION 'a cancelled evening (8, 11) holds slots, budget, logistics, feedback or a task in progress — move it by hand first'; END IF; END $$;
UPDATE mishmarim SET topic = (SELECT topic FROM mishmarim WHERE id = 8) WHERE id = 10 AND coalesce(topic, '') = '' AND (SELECT coalesce(topic, '') FROM mishmarim WHERE id = 8) <> '';
UPDATE speaker_searches SET mishmar_id = 10 WHERE mishmar_id = 8;
UPDATE speaker_outreach SET mishmar_id = 10 WHERE mishmar_id = 8;
DELETE FROM mishmarim WHERE id = 8 AND gregorian_date = '5.11.2026';   -- its template tasks and assignments cascade
DELETE FROM mishmarim WHERE id = 11 AND gregorian_date = '26.11.2026';   -- its template tasks and assignments cascade
DELETE FROM assignments WHERE mishmar_id BETWEEN 3 AND 21;
COMMIT;
