INSERT INTO students (id, name, role) SELECT top.id + 1, 'טליה קור', 'student' FROM (SELECT COALESCE(MAX(id), 0) AS id FROM students) top WHERE NOT EXISTS (SELECT 1 FROM students WHERE name = 'טליה קור');
